{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "resolution_time",
  "per_column": [
    {
      "name": "incident_category",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Category of the issue is known at open time and plausibly correlates with how long resolution takes (e.g., database vs email). Legitimate predictor outside the focus."
    },
    {
      "name": "problem_symptom_type",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Symptom type (outage vs cannot_connect) is knowable at intake and carries signal about complexity and time to resolve. Valid predictor."
    },
    {
      "name": "is_unassigned_at_open",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Whether an incident lacks an assignee at open time is knowable early and plausibly delays resolution. Legitimate predictor, no leakage."
    },
    {
      "name": "assignee_resolver_match",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Whether the assignee matches the resolver requires knowing who ultimately resolved/closed the incident, which is only determined after the outcome. This is post-hoc information correlated with the resolution process itself, constituting leakage."
    },
    {
      "name": "opened_hour_of_day",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Business vs off hours at open time is known before resolution and can affect response latency. Valid predictor derived from opened_at."
    },
    {
      "name": "is_recurring_issue_type",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Whether the issue type is recurring is knowable at intake (from category/symptom patterns) and plausibly relates to quicker resolution via known fixes. Legitimate predictor, though heavily skewed (462/38) so limited discriminative power."
    }
  ],
  "n_predictors": 5,
  "predictive_utility": 0.55,
  "rationale": "Five of six columns are legitimate, intake-time predictors that plausibly carry signal about resolution_time (category, symptom, unassigned-at-open, opened-hour, recurring-type), giving a model meaningful leverage beyond the raw fields. assignee_resolver_match is leakage because it depends on the eventual resolver/closer, information only available after the outcome. Some predictors are highly skewed, capping the incremental predictive leverage of the set."
}

